<?php require_once __DIR__.'/../config.php'; require_once __DIR__.'/../includes/functions.php';  $pageTitle='My Results'; require_role(['student']); require_once __DIR__.'/../includes/header.php';$st=$pdo->prepare('SELECT id FROM students WHERE user_id=?');$st->execute([user()['id']]);$sid=(int)$st->fetchColumn();$page=max(1,(int)($_GET['page']??1));$perPage=50;$offset=($page-1)*$perPage;$st=$pdo->prepare("SELECT r.*,sub.subject_name,t.session_name,t.term_name FROM results r JOIN subjects sub ON sub.id=r.subject_id JOIN academic_terms t ON t.id=r.term_id WHERE r.student_id=? ORDER BY t.id DESC,sub.subject_name LIMIT ? OFFSET ?");$st->bindValue(1,$sid,PDO::PARAM_INT);$st->bindValue(2,$perPage,PDO::PARAM_INT);$st->bindValue(3,$offset,PDO::PARAM_INT);$st->execute();$rows=$st->fetchAll();$count=$pdo->prepare('SELECT COUNT(*) FROM results WHERE student_id=?');$count->execute([$sid]);$pages=max(1,(int)ceil($count->fetchColumn()/$perPage));?><h2>My Results</h2><div class="card p-3 table-responsive"><table class="table"><thead><tr><th>Session/Term</th><th>Subject</th><th>CA</th><th>Exam</th><th>Total</th><th>Grade</th><th>Remarks</th></tr></thead><tbody><?php foreach($rows as $r): ?><tr><td><?=e($r['session_name'].' — '.$r['term_name'])?></td><td><?=e($r['subject_name'])?></td><td><?=$r['ca_score']?></td><td><?=$r['exam_score']?></td><td><?=$r['total']?></td><td><?=e($r['grade'])?></td><td><?=e($r['remarks'])?></td></tr><?php endforeach;?><?php if(!$rows): ?><tr><td colspan="7" class="text-muted">No results have been published for your account yet.</td></tr><?php endif;?></tbody></table></div><?php if($pages>1): ?><nav class="mt-3"><ul class="pagination"><?php for($i=1;$i<=$pages;$i++): ?><li class="page-item <?=$i===$page?'active':''?>"><a class="page-link" href="?page=<?=$i?>"><?=$i?></a></li><?php endfor;?></ul></nav><?php endif;?><?php require __DIR__.'/../includes/footer.php';
